---
-- Colors come straight from pywal's already-generated ~/.cache/wal/colors.sh
-- (plain shell var assignments, e.g. color0='#161320') rather than needing a
-- new custom Lua template - colors.sh gets regenerated by pywal on every
-- wallpaper change same as colors-hyprland.conf did, so nothing extra to set
-- up on the pywal side.
--
-- Hyprland wants colors as rgb(rrggbb) / rgba(rrggbbaa), not plain #hex, so
-- hexToRgb() strips the '#' and wraps it. Pass an alpha suffix (2 hex chars,
-- no '#') as the second arg if you want rgba(...) instead of rgb(...).

local function hexToRgb(hex, alpha)
    if not hex then return nil end
    local stripped = hex:gsub("^#", "")
    if alpha then
        return "rgba(" .. stripped .. alpha .. ")"
    end
    return "rgb(" .. stripped .. ")"
end
 
local function loadWalColors()
    local path = os.getenv("HOME") .. "/.cache/wal/colors.sh"
    local file = io.open(path, "r")
    if not file then
        return nil
    end
    local parsed = {}
    for line in file:lines() do
        -- matches `color0='#161320'`, `export color0='#161320'`, with or
        -- without quotes, tolerating either colors.sh convention
        local key, val = line:match("^%s*export%s+(%a+%d*)%s*=%s*['\"]?([^'\"%s]*)['\"]?%s*$")
        if not key then
            key, val = line:match("^%s*(%a+%d*)%s*=%s*['\"]?([^'\"%s]*)['\"]?%s*$")
        end
        if key and val and val ~= "" then
            parsed[key] = val
        end
    end
    file:close()
    return parsed
end

local walColors = loadWalColors()
local colors
if walColors and walColors.color0 and walColors.color6 and walColors.color15 then
    colors = {
        color0  = hexToRgb(walColors.color0, "ee"),
        color6  = hexToRgb(walColors.color6, "aa"),
        color15 = hexToRgb(walColors.color15, "ee"),
    }
else
    print("look.lua: couldn't read colors from ~/.cache/wal/colors.sh - using fallback colors")
    colors = {
        color0  = "rgba(1a1a1aee)",
        color6  = "rgba(595959aa)",
        color15 = "rgba(ffffffee)",
    }
end

